INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'fea78d10-6777-52bf-8c8b-c8f57527511d', '3c0e5050-ae0a-5908-ada0-af74b087dd4e',
  'Phát biểu nào sau đây là đúng khi so sánh array và list?

Lựa chọn:
- a. List và array hoàn toàn giống nhau về bản chất, chỉ khác nhau về tên gọi.
- b. Array có thể thay đổi được số lượng phần tử, còn list thì chỉ thay đổi đến sức chứa tối đa
- c. Array nằm rải rác trong vùng nhớ máy tính còn list thì tùy theo cách hiện thực.
- d. Array có kích thước là cố định, còn list có thể thay đổi được thông qua việc thêm và xóa phần tử.', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '61fcf67d-dd41-5748-a1a1-73d6211a7cb4', '3c0e5050-ae0a-5908-ada0-af74b087dd4e',
  'Cho sơ đồ bố trí con trỏ trên một danh sách liên kết hiện tại được viết bằng mã giả sau:

```text
head = Node(15)
temp1 = Node(16), head.next = temp1
temp2 = Node(17), temp1.next = temp2
tail = temp2
```

Đoạn mã giả nào dưới đây dùng để thêm xóa phần tử cuối ra khỏi danh sách?

Lựa chọn:
- temp1.next = NULL
 tail = temp1
- temp1 = head
 delete head
- head = temp1
 tail = temp2
- temp2 = tail
 delete temp2', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8f43bf67-3757-53b4-92cb-d063290c94cd', '3c0e5050-ae0a-5908-ada0-af74b087dd4e',
  'Cho sơ đồ bố trí con trỏ trên một danh sách liên kết hiện tại được viết bằng mã giả sau:

```text
head = Node(15)
temp1 = Node(16), head.next = temp1
temp2 = Node(17), temp1.next = temp2
tail = temp2
```

Đoạn mã giả nào dưới đây dùng để thêm một phần tử mang giá trị 18 vào cuối danh sách.

Chọn một:

Lựa chọn:
- a. temp2 = Node(18)
   temp2.next = tail
- b. temp = Node(18)
   tail = temp
   temp.next = temp2
- c. head = tail = Node(18)
   tail.next = null
- d. tail = Node(18)
   temp2.next = tail', 4
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c2333554-56c5-50ae-b3a2-58ea61ff0f34', '3c0e5050-ae0a-5908-ada0-af74b087dd4e',
  'Cho sơ đồ bố trí con trỏ trên một danh sách liên kết (bắt đầu từ head) hiện tại được viết bằng mã giả sau:

```text
temp1 = Node(30)
temp1.next = Node(17), temp2 = temp1
temp2.next = Node(42), temp2.next.next = Node(28)
head = temp1
```

Đoạn mã giả nào dưới đây dùng để thêm một phần tử mang giá trị 18 vào đầu danh sách.

Chọn một:

Lựa chọn:
- a. `head = tail = Node(18)`
   `tail.next = null`
- b. `temp = Node(18), head.next = temp1, head = temp`
- c. `temp = Node(18), temp.next = temp1, head = temp`
- d. `temp2 = Node(18)`
   `temp2.next = tail`', 5
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
